    # Check if the number is already an integer or a float
    if isinstance(n, int) or isinstance(n, float):
        return round(n)
    else:
        integer_part = int(n)
        fractional_part = n - integer_part

        # Determine the rounding direction
        if fractional_part >= 0.5:
            return integer_part + 1
        else:
            return integer_part

