def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

    requested_length = min([len(c) for c in cmd] + [len(str(a)) for a in varargs] + [_max_length],max_length)
    for v in varargs:
        requested_length = max(requested_length, len(v))
    if requested_length > _max_length:
        raise ValueError("requested length of xargs command lines exceeds _get_platform_max_length()")

    args = ' '.join(f"'{v}'" for v in varargs) or '""'
    cmd = f"{cmd[0]}{' ' + args if args else ''}"

    if color:
        p.stdin.write(f"\x1b[31m{cmd}\x1b[0m\n")
    else:
        p.stdin.write(f"{cmd}\n")

    return p.wait(), p.stdout.read().encode()

