def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    normalized = []
    for part in cmd:
        if part.startswith('#!'):
            if '\\\\' in part:
                # Replace backslashes with forward slashes for deep-paths
                normalized.append(part.replace('\\', '/'))
            else:
                normalized.append(part)
        else:
            normalized.append(part)
    return tuple(normalized)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    normalize = []
    for i in cmd:
        if i.startswith('#!'):
            # check if it's a full path shebang
            if len(i) > 2 and i[:2] == '/' and i[2:] in ["/bin/bash", "/bin/sh"]:
                i = f"{i.split('/')[-1]}"
            else:
                i = f"{i.split('/')[-2]}/{i.split('/')[-1]}"
        normalize.append(i)
    return tuple(normalize)

