def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    for item in fixity.inventory:
        path = item.path
        prefix = fixity.prefix
        if path not in manifest_files:
            raise IllegalArgumentException('File {} is not listed in the manifest and cannot be referenced in the fixity block. Fixity must reference files present in the manifest.')
        if not path.startswith(prefix):
            raise IllegalArgumentException('File {} does not start with the specified prefix {} and cannot be referenced in the fixity block. Fixity must reference files present in the manifest.')
    for entry in manifest_files:
