    groups_by_xml = {}
    for file in files:
        xml_placeholder, xml_file = os.path.split(file)
        xml_filename = xml_file.rsplit('/', 1)[0]

        if xml_file not in groups_by_xml:
            groups_by_xml[xml_file] = {}
        if xml_file not in groups_by_xml[xml_filename]:
            groups_by_xml[xml_filename][xml_file] = Package()

