        package.add_source(source)
        packages.add_file(file)

    return groups_by_xml

def _group_files_by_xml_filename(source, xmls, files):
    import os
    import zipfile

    reg = re.compile(r'\/(.*?)(\.xml)?')

    xml_filename = reg.search(source).group(1)

    if zipfile.is_zipfile(source):
        with zipfile.ZipFile(source) as z:
            return {os.path.splitext(i.isbn.filename)[0]: i for i in z.infolist() if i.filename.startswith(xml_filename) and i.filename.endswith('.xml')}
    else:
        f = open(source, 'rb')
        return {os.path.splitext(i.name)[0]: i for i in f if i.name.startswith(xml_filename) and i.name.endswith('.xml')}

