def _extract_number_and_supplement_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.

    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Extract the content of the issue element
    content = issue.text.strip()

    # Check if the content is empty
    if not content:
        return None, None

    # Initialize variables for the number and supplement
    number = None
    supplement = None

    # Iterate over each character in the content
    for char in content:
        if char.isdigit():
            if number is None:
                number = char
            else:
                number += char
        elif char.isalpha() and supplement is None and number is not None:
            if not supplement:
                supplement = char
            else:
                supplement += char

    return int(number) if number is not None else None, supplement

