def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    absorbed = []
    new_args = []
    for arg in args:
        if '+' in arg:
            absorbed.append(arg.split('+')[0])
        else:
            new_args.append(arg)

    for arg in new_args:
        if '-' in arg:
            absorbed.append(arg.split('-')[0])
        else:
            absorbed.append(arg)

    return absorbed

