import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        # Python 3.4 and later provides os.name (Windows, POSIX, etc.)
        if os.name == 'nt':
            return re.split('"([^\"]*?)"|"([^"]*?)"', re.escape(s), 2)
        else:
            return re.split('"([^"]*?)"|([^"]*?)"', re.escape(s), 3)
    elif platform == 1:
        # POSIX-style shell
        return re.split(r'"([^"]*?)"|"([^"]*?)"', re.escape(s), re.DOTALL)
    elif platform == 0:
        # Windows-style cmd
        return re.split(r'"([^"]*?)"|"([^"]*?)"', re.escape(s), re.UNICODE)
    else:
        raise ValueError('Unsupported platform value: {}'.format(platform))

