        stdout, stderr = process.communicate()
        return stdout.decode(), stderr.decode()
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Error: {e.stdout.decode()} {e.stderr.decode()}")
        if hide_stderr:
            return None, e.stdout.decode()
        else:
