def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, Hist):
        raise TypeError("hist must be a Hist instance")

    graph = Graph()
    x_data = []
    y_data = []

    for bin_ in hist:
        x = _get_coordinate(bin_, get_coordinate)
        y = make_value(bin_) if make_value else bin_()
        x_data.append(x)
        y_data.append(y)
        for graph_x, graph_y in _convert_to_graph_points(graph, field_names):
            graph.add_point(graph_x, graph_y)

    if scale is not None:
        graph.scale = scale

    return graph


def _get_coordinate(bin_, get_coordinate):
    if get_coordinate == "left":
        return bin_.left
    elif get_coordinate == "right":
        return bin_.right
    elif get_coordinate == "middle":
        return (bin_.left + bin_.right) / 2
    else:
        raise ValueError("invalid get_coordinate value: " + get_coordinate)


def _convert_to_graph_points(graph, field_names):
    for i in range(len(field_names)):
        yield field_names[i], graph.points[i]

