def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc:
        return explicit_mc

    metaclass = bases[-1]
    for base in bases[-2::-1]:
        if base is not object:
            if hasattr(base, '__metaclass__'):
                metaclass = base.__metaclass__

    return metaclass if metaclass is not tuple and metaclass is not object else None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    else:
        # exhaustively try each base's __metaclass__ to find one
        for base in bases:
            if hasattr(base, '__metaclass__'):
                return base.__metaclass__

        # last resort: use None (indicating no metaclass)
        return None

