def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Default to dynamic metaclass if no explicit one is provided
    if explicit_mc is None:
        explicit_mc = DynamicMetaClass

    # Sort bases in reverse order of dominance
    bases.sort(key=lambda base: getmro(base).index(MetaClass))

    # Determine the metaclass by looking for the first non-MetaClass base
    for base in bases:
        if not issubclass(base, MetaClass):
