from rdflib.namespace import RDFS, FOAF, DC, RDF

class DiasporaHostMeta:
    def __init__(self, host):
        self.host = host
        self.links = {}

    def add_link(self, rel, href):
        if rel in self.links:
            raise ValueError(f"Link with relation '{rel}' already exists.")
        self.links[rel] = href

    def to_rdf(self):
        rdf = FOAF.OBJECT.some(DC.METHOD.RDF2XML, datatype=XRD)
        rdf.addProperty(DC.METHOD.RDF2XML, DC.VALUE, RDF.type)
        rdf.addProperty(DC.METHOD.RDF2XML, DC.VALUE, RDFS.Comment)
        rdf.addProperty(DC.METHOD.RDF2XML, DC.VALUE, f'Forwards requests to {self.host}.')
        rdf.addProperty(DC.METHOD.RDF2XML, DC.VALUE, '<link rel="self" href="%s/">' % self.host)
        return RDF

