@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file:
            with open(yaml_file, 'r', encoding='utf-8') as yaml_file:
                document = yaml.safe_load(yaml_file)
        else:
            document = cls.get_default_document()

        for element_type, document_elements in document.items():
            element_type_class = cls.lookup_key(element_type)
            for element in document_elements:
                try:
                    element_type_class.validate(element)
                except IRValidatorException as e:
                    raise IRValidatorException(e.message)

